<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0, user-scalable=no, viewport-fit=cover"/>
<title>NPS</title>
<script src="https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.0.0/pdf.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.6.0/mammoth.browser.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js"></script>
<script src="https://js./v2/"></script>
<style>
/* ═══════ RESET & ROOT ═══════ */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#1a1b20;
  --bg2:#1f2028;
  --bg3:#252730;
  --bg4:#2c2e3a;
  --border:#2e3040;
  --accent:#E87A5D;
  --accent2:#f09070;
  --text:#e8e9f0;
  --text2:#9a9bb0;
  --text3:#5a5c70;
  --green:#4caf7d;
  --blue:#5b8af5;
  --r8:8px; --r12:12px; --r16:16px; --r20:20px;
  --sidebar:260px;
  --header:52px;
}

html,body{height:100%;overflow:hidden}
body{background:var(--bg);color:var(--text);font-family:-apple-system,'SF Pro Text','Segoe UI',Roboto,sans-serif;font-size:14px;display:flex;flex-direction:column;position:fixed;inset:0;touch-action:manipulation}

/* ═══════ HEADER ═══════ */
#app-header{
  height:var(--header);background:var(--bg);
  border-bottom:1px solid var(--border);
  display:flex;align-items:center;padding:0 14px;gap:10px;
  flex-shrink:0;z-index:10;
}
.hbtn{width:34px;height:34px;border-radius:var(--r8);background:none;border:none;color:var(--text2);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:18px;transition:background .15s}
.hbtn:hover{background:var(--bg3)}
.htitle{flex:1;font-size:15px;font-weight:600;color:var(--text);text-align:center;letter-spacing:.01em}
.haction{display:flex;gap:4px}

/* ═══════ LAYOUT ═══════ */
#layout{flex:1;display:flex;overflow:hidden;position:relative}

/* ═══════ SIDEBAR ═══════ */
#sidebar{
  width:var(--sidebar);background:var(--bg);
  border-right:1px solid var(--border);
  display:flex;flex-direction:column;
  flex-shrink:0;overflow:hidden;
  position:absolute;top:0;left:0;bottom:0;
  z-index:50;transform:translateX(-100%);
  transition:transform .28s cubic-bezier(.4,0,.2,1);
}
#sidebar.open{transform:none}
#sb-overlay{position:absolute;inset:0;background:rgba(0,0,0,.6);z-index:40;display:none;backdrop-filter:blur(2px)}
#sb-overlay.show{display:block}

.sb-top{padding:20px 16px 12px;border-bottom:1px solid var(--border)}
.sb-logo{
  width:48px;height:48px;
  animation:pulse-glow 4s ease-in-out infinite;
  margin-bottom:10px
}
@keyframes pulse-glow{
  0%,100%{filter:drop-shadow(0 0 4px rgba(232,122,93,.2))}
  50%{filter:drop-shadow(0 0 14px rgba(232,122,93,.55))}
}
.sb-brand{font-size:24px;font-weight:800;color:var(--text);letter-spacing:.06em}

.sb-nav{flex:1;overflow-y:auto;padding:10px 10px}
.sb-item{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:var(--r12);cursor:pointer;color:var(--text2);font-size:14px;transition:all .15s;margin-bottom:2px}
.sb-item:hover{background:var(--bg3);color:var(--text)}
.sb-item.active{background:var(--bg3);color:var(--text)}
.sb-item.accent{color:var(--accent)}
.sb-item.accent:hover{background:rgba(232,122,93,.08)}
.sb-icon{font-size:17px;flex-shrink:0;width:22px;text-align:center}
.sb-label{font-weight:500}
.sb-sep{height:1px;background:var(--border);margin:8px 0}
.sb-section{font-size:11px;font-weight:600;color:var(--text3);padding:6px 12px 4px;text-transform:uppercase;letter-spacing:.07em}
.sb-recent{padding:7px 12px;border-radius:var(--r8);cursor:pointer;color:var(--text2);font-size:13px;transition:all .15s;margin-bottom:1px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sb-recent:hover{background:var(--bg3);color:var(--text)}
.sb-recent.active{background:var(--accent);color:#fff;font-weight:600}
.sb-recent.active:hover{background:var(--accent)}

.sb-foot{padding:12px 12px;border-top:1px solid var(--border);display:flex;align-items:center;justify-content:space-between}
.sb-user{display:flex;align-items:center;gap:10px;flex:1;min-width:0}
.sb-av{width:32px;height:32px;border-radius:50%;background:var(--bg4);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:var(--text2);flex-shrink:0;border:1px solid var(--border)}
.sb-uname{font-size:13px;font-weight:600;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sb-gear{background:none;border:none;color:var(--text3);cursor:pointer;font-size:16px;padding:4px;border-radius:6px;flex-shrink:0}
.sb-gear:hover{color:var(--text2);background:var(--bg3)}

/* ═══════ MAIN ═══════ */
#main{flex:1;display:flex;flex-direction:column;overflow:hidden}

/* ═══════ CHAT VIEW ═══════ */
#chat-view{flex:1;display:flex;flex-direction:column;overflow:hidden}
#feed{flex:1;overflow-y:auto;padding:16px 12px 8px;display:flex;flex-direction:column;gap:16px;-webkit-overflow-scrolling:touch}
#feed::-webkit-scrollbar{width:3px}
#feed::-webkit-scrollbar-thumb{background:var(--border);border-radius:3px}

/* EMPTY STATE */
#empty-state{
  flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;
  gap:16px;padding:32px 20px;text-align:center
}
#empty-state .el-logo{
  width:72px;height:72px;
  animation:pulse-glow 4s ease-in-out infinite;
}
#empty-state h2{font-size:22px;font-weight:800;color:var(--text);letter-spacing:.04em}
#empty-state p{font-size:13px;color:var(--text2);max-width:260px;line-height:1.7}
.eg-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;width:100%;max-width:320px;margin-top:4px}
.eg-card{background:var(--bg2);border:1px solid var(--border);border-radius:var(--r12);padding:12px;cursor:pointer;text-align:left;transition:all .15s}
.eg-card:hover{border-color:var(--accent);background:var(--bg3)}
.eg-icon{font-size:20px;margin-bottom:6px}
.eg-title{font-size:11px;font-weight:600;color:var(--text);margin-bottom:3px}
.eg-sub{font-size:10px;color:var(--text2);line-height:1.5}

/* MESSAGES */
.msg-group{display:flex;flex-direction:column;gap:4px}
.msg-row{display:flex;gap:10px;align-items:flex-start}
.msg-row.user{flex-direction:row-reverse}
.msg-av{width:30px;height:30px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700}
.msg-av.bot{
  background:var(--bg2);border:1px solid var(--border);
  overflow:hidden;padding:2px;
}
.msg-av.bot svg{width:26px;height:26px}
.msg-av.user{background:var(--bg3);border:1px solid var(--border);color:var(--text2)}
.msg-bubble{
  max-width:78%;padding:10px 13px;border-radius:var(--r16);
  font-size:13px;line-height:1.65;word-break:break-word;
}
.msg-row.bot .msg-bubble{background:var(--bg2);border:1px solid var(--border);border-top-left-radius:4px;color:var(--text)}
.msg-row.user .msg-bubble{background:var(--bg3);border:1px solid var(--border);border-top-right-radius:4px;color:var(--text)}
.msg-time{font-size:10px;color:var(--text3);padding:0 4px;margin-top:2px;align-self:flex-end}
.msg-row.user .msg-time{text-align:right}

/* THINKING */
@keyframes spin { 100% { transform: rotate(360deg); } }

/* ═══════ COMPOSER ═══════ */
#composer{
  background:var(--bg);border-top:1px solid var(--border);
  padding:10px 12px;padding-bottom:max(10px,env(safe-area-inset-bottom));
  flex-shrink:0;
}
#comp-inner{
  background:var(--bg2);border:1px solid var(--border);
  border-radius:var(--r20);padding:10px 12px;
  display:flex;flex-direction:column;gap:8px;
}
#comp-input{
  background:none;border:none;color:var(--text);
  font-size:15px;outline:none;resize:none;
  max-height:120px;overflow-y:auto;
  line-height:1.55;font-family:inherit;
  placeholder-color:var(--text3);
}
#comp-input::placeholder{color:var(--text3)}
.comp-row{display:flex;align-items:center;justify-content:space-between}
.comp-left{display:flex;gap:4px}
.comp-cbtn{width:32px;height:32px;border-radius:50%;background:var(--bg3);border:1px solid var(--border);color:var(--text2);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:14px;transition:all .15s}
.comp-cbtn:hover{background:var(--bg4);color:var(--text)}
#send-btn{
  width:32px;height:32px;border-radius:50%;
  background:var(--accent);border:none;color:#fff;
  font-size:14px;cursor:pointer;display:flex;align-items:center;justify-content:center;
  transition:opacity .15s;flex-shrink:0
}
#send-btn:hover{opacity:.85}
#send-btn:disabled{opacity:.35;cursor:default}
#send-btn.mic{background:var(--bg3);border:1px solid var(--border);color:var(--text2)}
#send-btn.sending{background:var(--accent);border:none}
#send-btn.sending .send-icon{display:none}
#send-btn .stop-icon{display:none;width:11px;height:11px;background:#fff;border-radius:2px}
#send-btn.sending .stop-icon{display:block}

/* ═══════════ BANNIÈRE DE CONNEXION ═══════════ */
#conn-banner{
  position:fixed;left:12px;right:12px;top:calc(var(--header) + 8px);z-index:500;
  background:var(--bg3);border:1px solid var(--accent);border-radius:12px;
  padding:10px 14px;font-size:12.5px;color:var(--text);
  display:flex;align-items:center;gap:8px;
  transform:translateY(-140%);opacity:0;pointer-events:none;
  transition:transform .3s ease,opacity .3s ease;
  box-shadow:0 4px 16px rgba(0,0,0,.3);
}
#conn-banner.show{transform:translateY(0);opacity:1;pointer-events:auto}
#conn-banner .dot{width:7px;height:7px;border-radius:50%;background:#e0a855;flex-shrink:0;animation:connDotPulse 1s ease-in-out infinite}
@keyframes connDotPulse{0%,100%{opacity:1}50%{opacity:.3}}

/* ═══════ SETTINGS VIEW ═══════ */
.tts-rate-btn{
  background:var(--bg3);border:1px solid var(--border);color:var(--text);
  padding:9px 16px;border-radius:10px;font-size:13px;cursor:pointer;
}
.tts-rate-btn.active{background:var(--accent);border-color:var(--accent);color:#fff;font-weight:600}

/* Effet de balayage lumineux sur le titre "Processus de réflexion" tant que
   l'agent réfléchit encore — un dégradé qui traverse le texte du début à la
   fin, en boucle, pour montrer que ça avance sans surcharger l'utilisateur
   d'infos techniques. */
.nps-title-shimmer{
  background:linear-gradient(90deg, var(--text2) 0%, var(--text2) 35%, var(--text) 50%, var(--text2) 65%, var(--text2) 100%);
  background-size:200% 100%;
  -webkit-background-clip:text;
  background-clip:text;
  -webkit-text-fill-color:transparent;
  animation:npsShimmer 1.8s linear infinite;
}
@keyframes npsShimmer{
  0%{background-position:200% 0}
  100%{background-position:-200% 0}
}

/* Lecteur audio enchaîné (playlist TTS) : un seul contrôle visible, avance seul
   segment par segment plutôt que d'afficher N lecteurs à cliquer un par un. */
.chained-audio-wrap{margin-top:6px;max-width:320px}
.chained-audio-label{font-size:11px;color:var(--text3);margin-bottom:3px}
#settings-view{flex:1;overflow-y:auto;display:none;flex-direction:column}
.set-section{padding:20px 16px 8px;font-size:12px;font-weight:600;color:var(--text3);text-transform:uppercase;letter-spacing:.07em}
.set-card{background:var(--bg2);border-radius:var(--r16);margin:0 12px 10px;overflow:hidden;border:1px solid var(--border)}
.set-row{display:flex;align-items:center;gap:12px;padding:14px 16px;border-bottom:1px solid var(--border);cursor:pointer;transition:background .15s}
.set-row:last-child{border-bottom:none}
.set-row:hover{background:var(--bg3)}
.set-row-icon{width:32px;height:32px;border-radius:8px;background:var(--bg3);display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0;border:1px solid var(--border)}
.set-row-info{flex:1;min-width:0}
